import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Tasks and Durable Execution","description":"How Hearth turns intent into long-running work with recovery, evidence, budgets, and explicit completion.","frontmatter":{"title":"Tasks and Durable Execution","description":"How Hearth turns intent into long-running work with recovery, evidence, budgets, and explicit completion.","outline":false},"headers":[],"relativePath":"en/design/tasks.md","filePath":"en/design/tasks.md","lastUpdated":1793863446000}'),s={name:"en/design/tasks.md"};function o(i,e,d,c,l,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="tasks-and-durable-execution" tabindex="-1">Tasks and Durable Execution <a class="header-anchor" href="#tasks-and-durable-execution" aria-label="Permalink to &quot;Tasks and Durable Execution&quot;">​</a></h1><p class="lead">Hearth does not treat a request as a temporary conversation. It turns the request into a task that can continue across restarts, sleep, and network interruptions. Users see goals and progress; the system keeps work units, execution attempts, evidence, and recovery paths.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><p>A task needs a clear goal, acceptance method, deadline, budget, and cancellation path. Work can be divided into smaller work units, and each work unit has only one executor advancing it at a time. Every real attempt should retain its input, result, artifacts, failure reason, and whether work can continue.</p><p>A goal is not a sentence used as a task title; it is a separately stored contract. Acceptance criteria, evidence requirements, budget, deadline, stop conditions, and review policy live with the goal. Before a goal-backed task closes, the scheduler produces a completion report; without evidence the task can only remain waiting, become blocked, or go to human review. See <a href="/hearth-os/en/design/goals-and-evidence.html">Goals, Completion, and Evidence</a>.</p><p>Task state must be honest. Queued, running, waiting for approval, waiting for input, retrying, failed, paused, and completed are different states; none of them can be hidden behind &quot;processing&quot;. Users need to know why work stopped, how long it has been stopped, what happens next, and whether they must intervene.</p><p>Durable execution must cover real failures: service restarts, computer sleep, lost connectivity, executor crashes, external timeouts, offline devices, and version upgrades. After recovery, the system rechecks the goal and current state. It does not trust an old natural-language claim that work is complete, and it does not repeat external effects without verification.</p><p>The task graph expresses dependencies, parallelism, joins, compensation, and human steps. The first phase does not attempt to become a complete workflow platform. It implements only the sequencing, parallelism, waiting, and recovery needed for real tasks, avoiding a heavy engine introduced for architectural completeness.</p><h2 id="design-tradeoffs" tabindex="-1">Design Tradeoffs <a class="header-anchor" href="#design-tradeoffs" aria-label="Permalink to &quot;Design Tradeoffs&quot;">​</a></h2><p>Tasks, work units, execution attempts, and artifacts are stored separately. A task describes the result the user wants; a work unit describes a small authorized piece of work; an attempt describes one actual run; artifacts and receipts describe what was really delivered. Combining them into one object makes retries, budgets, and auditing confusing.</p><p>Facts come before in-memory state. Every state change is written to the local record before the interface and notifications are updated. The interface is only a projection and can be rebuilt after a crash. The early system uses one process, one writer, and a local database, with explicit timers, a pending-work queue, and checkpoints for recovery instead of microservices.</p><table tabindex="0"><thead><tr><th>Tradeoff</th><th>Hearth&#39;s choice</th><th>Cost and control</th></tr></thead><tbody><tr><td>Workflow implementation</td><td>Explicit state machines and a simple task graph</td><td>Complex flows need manual modeling, but behavior is easier to verify and recover</td></tr><tr><td>Execution right</td><td>One effective executor per work unit</td><td>Leases and expiry recovery are needed, but two executors cannot write at once</td></tr><tr><td>Failure handling</td><td>Verify first, then retry, switch executors, or ask for help</td><td>Recovery paths are richer, but blind retries cannot create duplicate effects</td></tr><tr><td>Long-running work</td><td>Save checkpoints and intermediate artifacts</td><td>More storage and cleanup rules, but work survives sleep and restarts</td></tr><tr><td>Budget</td><td>A hard limit and cancellation path at every level</td><td>Users may need to add budget, but the system cannot silently overspend</td></tr><tr><td>Uncertain external result</td><td>Reconcile first, do not retry directly</td><td>A person or connector must verify, but duplicate sends and writes are avoided</td></tr></tbody></table><p>A late result from an old executor cannot overwrite newer state. After a work unit is reassigned, a late submission is kept only as evidence; it cannot advance the task directly. If results must be merged, the current execution path verifies them again.</p><p>Recovery is not a simple rerun. After a process crash, work continues from the checkpoint. After a network interruption, pending actions are resubmitted with the same identity. When an executor times out, its workspace is saved and the system decides whether to change execution method. An offline device enters a device queue, and an uncertain external result enters reconciliation. Every recovery path gives the user an understandable reason and a next step.</p>',14)])])}const m=t(s,[["render",o]]);export{p as __pageData,m as default};
